import assert from 'node:assert/strict';

function fixture(core,T,api,examples,{dense=false}={}){
  const paint=new T.MeshStandardMaterial({vertexColors:true}),line=new T.LineBasicMaterial(),counts=new Map(),nodes=new Set(),faults=[];
  let borrowedDisposals=0,view=null,witness=null;paint.addEventListener('dispose',()=>borrowedDisposals++);line.addEventListener('dispose',()=>borrowedDisposals++);
  const bundle=dense?examples.tileArtBundle(core,[examples.surfaceRecipe('flat')],Array.from({length:16},(_,i)=>({id:'dense-'+i,recipeId:'flat',origin:[i*3,0,0]}))):examples.canonicalTileArtExample(core),projection=api.prepareTileArt(core,bundle);
  const options={materialForInstance:()=>paint,profileBindings:projection.entries.flatMap(e=>e.inspected.ports.map(p=>({profiles:p.profiles,boundaryMaterial:p.geometry.materialIntervals[0].material,material:paint}))),boundaryMaterial:line,showBoundaries:true};
  function geometry(g){if(!counts.has(g)){counts.set(g,0);g.addEventListener('dispose',()=>counts.set(g,counts.get(g)+1));}}
  function capture(node){node.traverse(n=>{nodes.add(n);if(n.geometry)geometry(n.geometry);});return node;}
  function top(node){while(node.parent)node=node.parent;capture(node);}
  function on(target,type,listener){target.addEventListener(type,listener);faults.push(()=>target.removeEventListener(type,listener));}
  function prototypeEvents(proto,listeners){const previous=Object.getOwnPropertyDescriptor(proto,'_listeners');Object.defineProperty(proto,'_listeners',{configurable:true,writable:true,value:listeners});faults.push(()=>{if(previous)Object.defineProperty(proto,'_listeners',previous);else delete proto._listeners;});}
  function build(extra={}){view=api.createTileArtProvider(T,projection,{...options,...extra});capture(view.root);for(const p of view.interfaces)geometry(p.geometry);return view;}
  function piece(id){const group=view.root.children.find(n=>n.name==='tile:'+id),localNodes=[];group.traverse(n=>localNodes.push(n));const geometries=[...new Set([...localNodes.filter(n=>n.geometry).map(n=>n.geometry),...view.interfaces.filter(p=>p.instanceId===id).map(p=>p.geometry)])];return {id,group,nodes:localNodes,geometries};}
  function gone(piece){for(const n of piece.nodes){assert.equal(n.parent===null,true,'Retired tile node remains parented.');assert.equal(n.children.length,0);}for(const g of piece.geometries)assert.equal(counts.get(g),1,'Owned geometry disposal is not exactly once.');}
  function empty(){const d=view.diagnostics();assert.equal(d.disposed,true);for(const k of ['instances','interfaces','ownedGeometry','triangles','quantizationLimitedRefinements'])assert.equal(d[k],0,'Nonzero/negative final counter '+k);assert.equal(view.root.parent===null,true);assert.equal(view.root.children.length,0);for(const [g,n]of counts)assert.equal(n,1,'Final resource not retired once.');assert.equal(borrowedDisposals,0);}
  function close(){for(const undo of faults.reverse())undo();try{view?.dispose();}catch{}for(const n of [...nodes].reverse()){n.removeFromParent();for(const child of [...n.children])n.remove(child);}for(const [g,n]of counts)if(n===0)g.dispose();assert.equal(borrowedDisposals,0);paint.dispose();line.dispose();}
  return {core,T,api,examples,projection,options,paint,line,counts,nodes,on,prototypeEvents,capture,top,geometry,build,piece,gone,empty,close,get view(){return view;},setWitness:value=>{witness=value;},get witness(){return witness;},borrowed:()=>borrowedDisposals};
}
const cleanupFailure=action=>assert.throws(action,e=>e instanceof AggregateError&&e.code==='TILE_ART_LIFECYCLE_FAILED');
const cases=[
  {name:'throwing first dispose listener cannot strand target, neighbours or final resources',run(f){const v=f.build(),target=f.piece('paving-a'),neighbour=f.piece('paving-b');assert.equal(f.counts.size,17);f.on(target.geometries[0],'dispose',()=>{throw Error('first owned geometry');});let failure;try{v.removeInstance(target.id);}catch(e){failure=e;}const afterRemove=v.diagnostics();try{v.dispose();}catch{}const end=v.diagnostics();f.setWitness({created:f.counts.size,afterRemove,end,attempted:[...f.counts.values()]});assert.ok(failure instanceof AggregateError);assert.equal(afterRemove.instances,4);assert.equal(afterRemove.ownedGeometry,12);f.gone(target);f.gone(neighbour);f.empty();v.dispose();f.empty();}},
  {name:'throwing removed listener cannot double-decrement counters on global retry',run(f){const v=f.build(),target=f.piece('paving-a'),before=v.diagnostics();f.on(target.group,'removed',()=>{throw Error('removed tile group');});let failure;try{v.removeInstance(target.id);}catch(e){failure=e;}const afterRemove=v.diagnostics();try{v.dispose();}catch{}const end=v.diagnostics();f.setWitness({before,afterRemove,end});assert.ok(failure instanceof AggregateError);assert.equal(afterRemove.instances,4);assert.ok(afterRemove.triangles>=0);assert.equal(v.removeInstance(target.id),false);f.gone(target);f.empty();}},
  {name:'dispose requested by a geometry listener drains once without recursive removal',run(f){const v=f.build(),target=f.piece('paving-a');f.on(target.geometries[0],'dispose',()=>v.dispose());assert.equal(v.removeInstance(target.id),true);f.empty();v.dispose();f.empty();}},
  {name:'removed/dispose failures during full disposal attempt every resource and keep borrowed scene',run(f){const v=f.build(),scene=new f.T.Scene(),sentinel=new f.T.Group(),target=f.piece('paving-a');scene.add(sentinel,v.root);f.on(target.group,'removed',()=>{throw Error('removed fault');});f.on(target.geometries[0],'dispose',()=>{throw Error('dispose fault');});cleanupFailure(()=>v.dispose());f.empty();assert.deepEqual(scene.children.map(n=>n.id),[sentinel.id]);v.dispose();f.empty();}},
  {name:'nested remove/cull reject while readonly diagnostics and neighbour attributes stay valid',run(f){const v=f.build(),target=f.piece('paving-a'),neighbour=f.piece('paving-b'),saved=neighbour.geometries.map(g=>Array.from(g.attributes.position.array));let rejected=0;
    const observe=()=>{for(const call of [()=>v.removeInstance('paving-b'),()=>v.setResident([])]){assert.throws(call,e=>e.code==='REENTRANT_LIFECYCLE');rejected++;}const d=v.diagnostics();assert.equal(d.instances,4);assert.ok(d.triangles>=0);assert.equal(v.interfaces.some(p=>p.instanceId===target.id),false);};f.on(target.group,'removed',observe);f.on(target.geometries[0],'dispose',observe);assert.equal(v.removeInstance(target.id),true);assert.equal(rejected,4);f.gone(target);for(const [i,g]of neighbour.geometries.entries()){assert.equal(f.counts.get(g),0);assert.deepEqual(Array.from(g.attributes.position.array),saved[i]);}v.setResident(['paving-b']);assert.equal(neighbour.group.visible,true);assert.equal(f.borrowed(),0);
  }},
  {name:'actual added listener failure plus rollback dispose failure clears constructor ownership',run(f){let fault;
    f.prototypeEvents(f.T.Group.prototype,{added:[function(){f.top(this);if(!fault&&this.name==='tile:paving-a'){fault=[...f.counts.keys()][0];f.on(fault,'dispose',()=>{throw Error('rollback dispose');});}if(this.name==='tile:paving-b')throw Error('actual Group added failure');}]});cleanupFailure(()=>f.build());assert.equal(f.counts.size,10);for(const n of f.nodes){assert.equal(n.parent===null,true);assert.equal(n.children.length,0);}for(const n of f.counts.values())assert.equal(n,1);assert.equal(f.borrowed(),0);
  }},
  {name:'actual partial mesh attachment rollback retires unparented nodes and all interface buffers',run(f){let fault;
    const added=function(){f.top(this);if(!fault){fault=this.geometry;f.on(fault,'dispose',()=>{throw Error('partial rollback observer');});}if(this.name==='tile-surface:paving-b')throw Error('partial Mesh added failure');};f.prototypeEvents(f.T.Mesh.prototype,{added:[added]});f.prototypeEvents(f.T.Line.prototype,{added:[function(){f.top(this);}]});f.prototypeEvents(f.T.Group.prototype,{added:[function(){f.top(this);}]});cleanupFailure(()=>f.build());assert.equal(f.counts.size,6);for(const n of f.nodes){assert.equal(n.parent===null,true);assert.equal(n.children.length,0);}for(const n of f.counts.values())assert.equal(n,1);
  }},
  {name:'borrowed material callback failure and throwing rollback listeners preserve every prior resource',run(f){let fault;
    f.prototypeEvents(f.T.Group.prototype,{added:[function(){f.top(this);if(!fault){fault=[...f.counts.keys()][0];f.on(fault,'dispose',()=>{throw Error('material rollback observer');});}}]});cleanupFailure(()=>f.build({materialForInstance:entry=>{if(entry.instanceId==='paving-b')throw Error('material acquisition refused');return f.paint;}}));assert.equal(f.counts.size,5);for(const n of f.nodes){assert.equal(n.parent===null,true);assert.equal(n.children.length,0);}for(const n of f.counts.values())assert.equal(n,1);
  }},
  {name:'removed/dispose reparenting cannot retain owned parents or disturb borrowed scene siblings',run(f){const v=f.build(),host=new f.T.Group(),sentinel=new f.T.Group(),target=f.piece('paving-a');host.add(sentinel,v.root);f.on(target.group,'removed',()=>{host.add(target.group);throw Error('removed reparent');});f.on(target.geometries[0],'dispose',()=>{host.add(target.nodes.at(-1));throw Error('dispose reparent');});cleanupFailure(()=>v.removeInstance(target.id));f.gone(target);assert.deepEqual(host.children.map(n=>n.id),[sentinel.id,v.root.id]);f.on(v.root,'removed',()=>{host.add(v.root);v.dispose();throw Error('outer reparent');});cleanupFailure(()=>v.dispose());f.empty();assert.deepEqual(host.children.map(n=>n.id),[sentinel.id]);}},
  {name:'error reporting is bounded while all dense-chunk resources retire',dense:true,run(f){const v=f.build();for(const node of f.nodes)f.on(node,'removed',()=>{throw Error('removed observer');});for(const g of f.counts.keys())f.on(g,'dispose',()=>{throw Error('dispose observer');});let failure;try{v.dispose();}catch(e){failure=e;}assert.ok(failure instanceof AggregateError);assert.equal(failure.code,'TILE_ART_LIFECYCLE_FAILED');assert.equal(failure.errors.length,64);assert.ok(failure.failureCount>64);f.empty();v.dispose();f.empty();}}
];
export const tileLifecycleCaseNames=cases.map(c=>c.name);
export function runTileLifecycleCase(core,T,api,examples,index,{baseline=false}={}){
  const entry=cases[index],f=fixture(core,T,api,examples,entry);try{entry.run(f);return {name:entry.name,status:'pass',...(f.witness?{observed:f.witness}:{})};}catch(error){if(!baseline)throw error;return {name:entry.name,status:'fail',reason:error.message.slice(0,1024),...(f.witness?{observed:f.witness}:{})};}finally{f.close();}
}
export function tileLifecycleProof(core,T,api,examples,{baseline=false}={}){const results=cases.map((_,i)=>runTileLifecycleCase(core,T,api,examples,i,{baseline}));return {status:results.every(r=>r.status==='pass')?'pass':'fail',actualThreeRevision:T.REVISION,actualPublicCore:true,cases:results.length,results,borrowedPoolSurvival:true};}
